31	/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
32	/// newest-first, grouped by day, each card marked by origin. Replaces the
33	/// former `MeusRegistrosPlaceholderScreen`.
34	///
35	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
36	/// closes it (`BlocProvider.value`, same convention
37	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
38	/// this screen's own [ScrollController] is this `State`'s to dispose.
39	///
40	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
41	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
42	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
43	/// rebuilt from scratch underneath it, so [_scrollController]'s position
44	/// and [cubit]'s state survive that overlay appearing with no extra code
45	/// needed here (Acceptance Criteria's third bullet).
46	class MeusRegistrosScreen extends StatefulWidget {
47	  const MeusRegistrosScreen({
48	    required this.cubit,
49	    required this.searchCubit,
50	    super.key,
51	  });
52	
53	  final MeusRegistrosCubit cubit;
54	
55	  /// spec-5-1 — the permanently-docked `EntriesSearchBar`'s own cubit, a DI
56	  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
57	  /// closes it either, same rationale [cubit]'s own doc above gives.
58	  final EntriesSearchCubit searchCubit;
59	
60	  @override
61	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
62	}
63	
64	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
65	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
66	  // `BootSplashScreen`.
67	  static const _skeletonThreshold = Duration(milliseconds: 300);
68	
69	  final ScrollController _scrollController = ScrollController();
70	  Timer? _skeletonTimer;
71	  bool _showSkeleton = false;
72	
73	  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
74	  /// mirroring [_skeletonTimer]/[_showSkeleton] above but keyed off
75	  /// `EntriesSearchCubit`'s `ResourceLoading` rather than
76	  /// `MeusRegistrosLoading`: started fresh on every transition into
77	  /// `ResourceLoading` (`_onSearchStateChanged` below), since unlike the
78	  /// first-load timer above (started once, in [initState]) a search can
79	  /// enter/leave loading many times across one screen visit.
80	  Timer? _searchSkeletonTimer;
81	  bool _showSearchSkeleton = false;
82	
83	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
84	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
85	  /// detail-route instances); cleared once the pushed route is popped, via
86	  /// `whenComplete` below.
87	  bool _navigatingToDetail = false;
88	
89	  /// Review finding (edge-case-hunter layer, spec-7-1) — same rationale as
90	  /// [_navigatingToDetail] above, for `_onExportTap`: guards against a
91	  /// rapid double-tap on the export icon opening a second
92	  /// `showDateRangePicker`/creating a second job while the first tap's own
93	  /// awaited chain is still in flight. Cleared in every exit path of
94	  /// `_onExportTap` (`finally`).
95	  bool _exportInFlight = false;
96	
97	  @override
98	  void initState() {
99	    super.initState();
100	    widget.cubit.loadFirstPage();
101	    // spec-5-3 — both `cubit`/`searchCubit` are `lazySingleton`s (Code
102	    // Map): a fresh mount of this screen must reset both, not just
103	    // `cubit`'s own filters above, or a re-entered screen would carry a
104	    // stale filter selection from a previous visit into a still-active
105	    // search (Boundaries: "Re-enter screen after a prior combined
106	    // session").
107	    widget.searchCubit.updateFilters(
108	      source: null,
109	      dateFrom: null,
110	      dateTo: null,
111	    );
112	    _skeletonTimer = Timer(_skeletonThreshold, () {
113	      if (mounted) {
114	        setState(() => _showSkeleton = true);
115	      }
116	    });
117	    _scrollController.addListener(_onScroll);
118	    // Review finding: `searchCubit` is a long-lived singleton (Code Map)
119	    // that can already be `ResourceLoading` the moment this `State` is
120	    // (re)created — e.g. the user switches tabs away mid-search and back,
121	    // which tears down and rebuilds this plain `GoRoute`'s widget while the
122	    // DI-singleton cubit keeps running. `BlocConsumer`'s `listener` below
123	    // only fires on a *new* state, never for one already current at
124	    // subscription time, so without this check the search skeleton would
125	    // never arm for an in-flight search resumed this way.
126	    if (widget.searchCubit.state is ResourceLoading<List<Entry>>) {
127	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
128	        if (mounted) {
129	          setState(() => _showSearchSkeleton = true);
130	        }
131	      });
132	    }
133	  }
134	
135	  @override
136	  void dispose() {
137	    _skeletonTimer?.cancel();
138	    _searchSkeletonTimer?.cancel();
139	    _scrollController
140	      ..removeListener(_onScroll)
141	      ..dispose();
142	    super.dispose();
143	  }
144	
145	  /// `BlocConsumer<EntriesSearchCubit, ...>`'s own listener (below) — starts
146	  /// [_searchSkeletonTimer] fresh on every transition into
147	  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
148	  /// but re-armed per search rather than once per screen visit; any other
149	  /// state (including a fast resolve before the 300ms threshold, RNF01)
150	  /// cancels it and resets [_showSearchSkeleton].
151	  void _onSearchStateChanged(
152	    BuildContext context,
153	    Resource<List<Entry>> state,
154	  ) {
155	    _searchSkeletonTimer?.cancel();
156	    if (state is ResourceLoading<List<Entry>>) {
157	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
158	        if (mounted) {
159	          setState(() => _showSearchSkeleton = true);
160	        }
161	      });
162	      return;
163	    }
164	    if (_showSearchSkeleton) {
165	      setState(() => _showSearchSkeleton = false);
166	    }
167	  }
168	
169	  void _openDetail(Entry entry) {
170	    if (_navigatingToDetail) {
171	      return;
172	    }
173	    _navigatingToDetail = true;
174	    context
175	        .push(
176	          '${AppRoutePaths.meusRegistros}/'
177	          '${Uri.encodeComponent(entry.id)}',
178	        )
179	        .whenComplete(() {
180	          if (mounted) {
181	            setState(() => _navigatingToDetail = false);
182	          } else {
183	            _navigatingToDetail = false;
184	          }
185	        });
186	  }
187	
188	  /// spec-7-1 — the header's download icon: opens a free-form period
189	  /// picker (Design Notes: `showDateRangePicker`, docs/input silent on
190	  /// the widget), then creates the export job (`ExportJobCubit.start()`).
191	  /// A create failure never opens the sheet (Boundaries) — an inline
192	  /// `SnackBar` with the mapped `Failure.message` instead, and the
193	  /// one-shot cubit is closed immediately rather than left to
194	  /// `ExportStatusSheet.show()`'s own disposal (which never runs, since
195	  /// the sheet itself never opens on this path). spec-7-3's one
196	  /// exception: an `EXPORT_EMPTY_PERIOD` create failure makes
197	  /// `ExportJobCubit.start()` return `true` instead, so it falls through
198	  /// to the same `ExportStatusSheet.show()` call below and opens
199	  /// directly on "Período vazio".
200	  Future<void> _onExportTap() async {
201	    if (_exportInFlight) {
202	      return;
203	    }
204	    _exportInFlight = true;
205	    try {
206	      final now = DateTime.now();
207	      final range = await showDateRangePicker(
208	        context: context,
209	        firstDate: DateTime(2000),
210	        lastDate: now,
211	        initialDateRange: DateTimeRange(
212	          start: now.subtract(const Duration(days: 30)),
213	          end: now,
214	        ),
215	      );
216	      if (range == null || !mounted) {
217	        return;
218	      }
219	      final exportCubit = sl<ExportJobCubit>();
220	      final started = await exportCubit.start(
221	        periodStart: range.start,
222	        periodEnd: range.end,
223	      );
224	      if (!mounted) {
225	        await exportCubit.close();
226	        return;
227	      }
228	      if (!started) {
229	        final message = switch (exportCubit.state) {
230	          ExportJobError(failure: final failure) => failure.message,
231	          _ => 'Não foi possível solicitar a exportação.',
232	        };
233	        await exportCubit.close();
234	        if (!mounted) {
235	          return;
236	        }
237	        ScaffoldMessenger.of(context)
238	            .showSnackBar(SnackBar(content: Text(message)));
239	        return;
240	      }
241	      await ExportStatusSheet.show(context, cubit: exportCubit);
242	    } finally {
243	      _exportInFlight = false;
244	    }
245	  }
246	
247	  void _onScroll() {
248	    if (!_scrollController.hasClients) {
249	      return;
250	    }
251	    final position = _scrollController.position;
252	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
253	    // purely as a scroll-distance buffer, not a new literal) for a
254	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
255	    // there's no further page or a call is already in flight.
256	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
257	      widget.cubit.loadMore();
258	    }
259	  }
260	
261	  @override
262	  Widget build(BuildContext context) {
263	    return MultiBlocProvider(
264	      providers: [
265	        BlocProvider.value(value: widget.cubit),
266	        BlocProvider.value(value: widget.searchCubit),
267	      ],
268	      child: Scaffold(
269	        backgroundColor: DesignTokens.colorSurfaceBg,
270	        body: Column(
271	          children: [
272	            BackArrowHeader(
273	              title: 'Meus Registros',
274	              trailing: _ExportIconButton(onTap: _onExportTap),
275	            ),
276	            Padding(
277	              padding: const EdgeInsets.fromLTRB(
278	                DesignTokens.spacingMd,
279	                DesignTokens.spacingMd,
280	                DesignTokens.spacingMd,
281	                0,
282	              ),
283	              // spec-5-2: `hasActiveFilters`/`onFilterTap` need the real
284	              // `MeusRegistrosCubit` — this now rebuilds on its state too,
285	              // while `EntriesSearchBar` itself stays a dumb, stateless
286	              // widget, same as before. spec-5-3 (Boundaries: "Funnel fill
287	              // ... drops its ResourceIdle gate — becomes
288	              // widget.cubit.hasActiveFilters unconditionally"): a filter
289	              // now also narrows an active search (via `searchCubit.
290	              // updateFilters()`), so the funnel reads as "filled"
291	              // whenever a filter is active, regardless of which surface
292	              // — plain timeline or search results — is currently on
293	              // screen; no `EntriesSearchCubit` rebuild needed here
294	              // anymore.
295	              child: BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
296	                builder: (context, _) => EntriesSearchBar(
297	                  onChanged: widget.searchCubit.onQueryChanged,
298	                  onFilterTap: () => EntriesFilterSheet.show(
299	                    context,
300	                    cubit: widget.cubit,
301	                    searchCubit: widget.searchCubit,
302	                  ),
303	                  hasActiveFilters: widget.cubit.hasActiveFilters,
304	                ),
305	              ),
306	            ),
307	            Expanded(
308	              child: BlocConsumer<EntriesSearchCubit, Resource<List<Entry>>>(
309	                listener: _onSearchStateChanged,
310	                builder: (context, searchState) {
311	                  // Boundaries: "an empty query reverts to the normal
312	                  // timeline" — `ResourceIdle` is the only variant that
313	                  // falls through to the pre-existing
314	                  // `MeusRegistrosCubit`-driven timeline below; every other
315	                  // variant renders the search surface instead.
316	                  if (searchState is ResourceIdle<List<Entry>>) {
317	                    return BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
318	                      builder: (context, state) {
319	                        final timeline = switch (state) {
320	                          MeusRegistrosLoading() =>
321	                            _showSkeleton
322	                                ? const _SkeletonList()
323	                                : const SizedBox.shrink(),
324	                          MeusRegistrosEmpty() => const _EmptyState(),
325	                          MeusRegistrosError(message: final message) =>
326	                            _ErrorState(
327	                              message: message,
328	                              // Code-review fix: `retryCurrentPage()`, not
329	                              // `loadFirstPage()` — the latter resets the
330	                              // active filter selection, silently turning
331	                              // a failed *filtered* retry into a
332	                              // successful unfiltered one.
333	                              onRetry: widget.cubit.retryCurrentPage,
334	                            ),
335	                          MeusRegistrosLoaded() => _EntryList(
336	                            state: state,
337	                            scrollController: _scrollController,
